import{_ as n,o as s,c as t,ah as a}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Notes des EC (enseignement supérieur)","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/enseignant/notes-superieur.md","filePath":"src/guide/enseignant/notes-superieur.md"}'),o={name:"guide/enseignant/notes-superieur.md"};function r(l,e,i,u,d,p){return s(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="notes-des-ec-enseignement-superieur" tabindex="-1">Notes des EC (enseignement supérieur) <a class="header-anchor" href="#notes-des-ec-enseignement-superieur" aria-label="Permalink to &quot;Notes des EC (enseignement supérieur)&quot;">​</a></h1><p>Dans une filière de l&#39;enseignement supérieur, vous notez des <strong>éléments constitutifs (EC)</strong>, promotion par promotion. Le responsable de la filière vous les confie depuis la page <strong>Enseignements</strong> de chaque promotion.</p><p>Vos EC sont dans <strong>Supérieur → Notes des EC</strong>. Chaque ligne donne la promotion, l&#39;UE et la période, avec deux feuilles : <strong>Session normale</strong> et <strong>Rattrapage</strong>.</p><h2 id="la-session-normale" tabindex="-1">La session normale <a class="header-anchor" href="#la-session-normale" aria-label="Permalink to &quot;La session normale&quot;">​</a></h2><p>La feuille liste les étudiants qui suivent l&#39;EC : toute la promotion pour une UE obligatoire, les seuls inscrits pour une UE optionnelle.</p><p>Pour chacun, saisissez sur 20 :</p><ul><li>le <strong>contrôle continu</strong> ;</li><li>l&#39;<strong>examen</strong>, ou cochez <strong>Absent</strong> : une absence à l&#39;examen vaut 0.</li></ul><p>La colonne <strong>Note de l&#39;EC</strong> se calcule pendant la saisie, selon la part du contrôle continu fixée par la filière (40 % par défaut). Elle s&#39;affiche en orange sous la note de validation. Cliquez sur <strong>Enregistrer les notes</strong>.</p><p>Une ligne vidée efface les notes de l&#39;étudiant : ce n&#39;est pas un zéro.</p><div class="tip custom-block"><p class="custom-block-title">Selon la filière</p><p>Certaines filières notent leurs EC au seul contrôle continu ou au seul examen : la feuille n&#39;affiche alors que la colonne utile.</p></div><h2 id="le-rattrapage" tabindex="-1">Le rattrapage <a class="header-anchor" href="#le-rattrapage" aria-label="Permalink to &quot;Le rattrapage&quot;">​</a></h2><p>La feuille de rattrapage ne liste que les étudiants qui doivent le passer : leur UE n&#39;est pas validée après la session normale (compensation comprise) et leur note à cet EC est sous la note de validation.</p><p>Saisissez la note de l&#39;<strong>examen de rattrapage</strong>, ou cochez <strong>Absent</strong>. Elle remplace l&#39;examen de la session normale ; le contrôle continu reste acquis. La filière décide ensuite de la note que garde l&#39;EC : celle du rattrapage, la meilleure des deux, ou celle du rattrapage plafonnée.</p><h2 id="les-etudiants-en-dette" tabindex="-1">Les étudiants en dette <a class="header-anchor" href="#les-etudiants-en-dette" aria-label="Permalink to &quot;Les étudiants en dette&quot;">​</a></h2><p>Une feuille peut aussi lister des étudiants d&#39;une promotion supérieure qui doivent encore l&#39;UE : ils portent la mention <strong>Dette</strong> et le nom de leur promotion. Notez-les comme les autres, en session normale et au rattrapage. Leur note est figée quand le jury de leur propre promotion a délibéré.</p><p>Les notes d&#39;une session sont figées quand le jury délibère sur l&#39;année. Si la filière délibère aussi à chaque semestre, celles d&#39;un semestre le sont dès que sa délibération est publiée ; les notes de l&#39;autre semestre restent modifiables.</p><h2 id="une-annee-cloturee" tabindex="-1">Une année clôturée <a class="header-anchor" href="#une-annee-cloturee" aria-label="Permalink to &quot;Une année clôturée&quot;">​</a></h2><p>Quand l&#39;année est clôturée, ses feuilles restent consultables mais ne peuvent plus être modifiées.</p>',18)])])}const m=n(o,[["render",r]]);export{g as __pageData,m as default};
